INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Pitch Live: Stand Out in a Sea of AI Pitches', 'Philadelphia Startup Founder 101', 'Founders & Startups', 'Your pitch has a problem you cannot hear. You have said it enough times that it sounds fine to you. Mentors hear it in the first ninety', 'Your pitch has a problem you cannot hear. You have said it enough times that it sounds fine to you. Mentors hear it in the first ninety seconds. In this session founders pitch live and get structured feedback on the spot, and everyone else learns from watching someone else''s mistake instead of making it. Bring a pitch at any stage, including one that is still only an idea. Register now and say it out loud to people who will tell you the truth. **❯ Guest Speakers include:** * Drew Chapin More info: https://www.meetup.com/philadelphia-startup-founder-101/events/316784639/', '2026-10-13T18:00:00-04:00', 'Online event', 'Online event', 'Philadelphia', 'PA', '', 40.12, -75.01, 'Philadelphia Startup Founder 101', 4, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/philadelphia-startup-founder-101/events/316784639/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('U.S. Visas & Immigration 101 for Startup Founders', 'Philadelphia Startup Founder 101', 'Founders & Startups', 'Building a company in the U.S. is hard enough. Doing it as a non-citizen founder means navigating an immigration system that was never', 'Building a company in the U.S. is hard enough. Doing it as a non-citizen founder means navigating an immigration system that was never designed with startups in mind. This 101 session breaks down the essentials in plain English. You''ll get a clear map of the visa paths open to founders, how they differ, and what each one actually asks of you when you''re the one building the company. We''ll also look at how milestones like fundraising and revenue shape your options, and the mistakes that quietly More info: https://www.meetup.com/philadelphia-startup-founder-101/events/316753093/', '2026-10-12T12:00:00-04:00', 'Online event', 'Online event', 'Philadelphia', 'PA', '', 40.12, -75.01, 'Philadelphia Startup Founder 101', 5, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/philadelphia-startup-founder-101/events/316753093/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
