INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Green Flags and the Right Job: A Networking Event', 'Portland Women in Technology (PDXWIT)', 'Women in Business', 'This is a Focused Networking Event for PDXWIT! I want everyone to leave with something valuable, not just more connections, (no matter how', 'This is a Focused Networking Event for PDXWIT! I want everyone to leave with something valuable, not just more connections, (no matter how important I think your network is!) Think of a job that turned out to be worth it. What did you notice during the interview process that told you so, and how could someone else spot it? Be prepared to come to the event with something to share and sit down with a beer at Migration Brewery on Williams to meet with your fellow PDXWIT members and learn how we More info: https://www.meetup.com/portland-women-in-technology/events/316754196/', '2026-10-28T17:30:00-07:00', 'Migration Brewing Williams x 5 Star', '3947 N Williams Ave, Portland, OR 97227, USA', 'Portland', 'OR', '97227', 45.551286332271, -122.666808079778, 'Portland Women in Technology (PDXWIT)', 46, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/portland-women-in-technology/events/316754196/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Portland Women Investors Fall Meetup', 'Portland Women Investors', 'Real Estate', 'Now that we are back into the swing of the fall, let’s get together! We are going to mix things up a little bit this year; rather than', 'Now that we are back into the swing of the fall, let’s get together! We are going to mix things up a little bit this year; rather than focusing on specific topics each meeting, we will do more social gathering/networking meetings. There will still be an opportunity to share resources or ask questions, but since we haven’t all been together for a while so it will be great to just hang! ***Please be sure to RSVP here on Meetup!*** As always, no investing experience is required to join any of our More info: https://www.meetup.com/portland-women-investors/events/316856003/', '2026-10-21T17:30:00-04:00', 'Après', '148 Anderson St, Portland, ME 04101, USA', 'Portland', 'ME', '04101', 43.667533790602, -70.25580011807, 'Portland Women Investors', 7, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/portland-women-investors/events/316856003/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
